import itertools
import json

def solve():
    houses = [1, 2, 3, 4, 5]  # positions left-to-right
    idx = {h: h - 1 for h in houses}  # 1-based to 0-based helper

    Names = ["Alice", "Eric", "Arnold", "Bob", "Peter"]
    Flowers = ["tulips", "roses", "lilies", "daffodils", "carnations"]
    Animals = ["dog", "horse", "cat", "bird", "fish"]

    # Pre-allocate name positions with known constraints:
    # 1) Alice is in the second house.
    # 8) Alice is directly left of the person who keeps horses.
    # 5) The person who keeps horses is Eric.
    # From 1, 8, 5 -> Alice at house 2 (index 1), Eric must be at house 3 (index 2).
    fixed_names = [None] * 5
    fixed_names[1] = "Alice"
    fixed_names[2] = "Eric"

    unknown_name_positions = [i for i, v in enumerate(fixed_names) if v is None]
    remaining_names = [n for n in Names if n not in fixed_names]

    solutions = []

    for perm_names in itertools.permutations(remaining_names):
        names_by_house = fixed_names[:]
        for pos, name in zip(unknown_name_positions, perm_names):
            names_by_house[pos] = name

        pos_name = {name: i for i, name in enumerate(names_by_house)}

        # Enforce name-only derived constraints:
        # Ensure Eric is immediately right of Alice (from clues 8 and 5)
        if pos_name["Eric"] != pos_name["Alice"] + 1:
            continue

        # From 7 and 4: fish immediately left of Bob and fish==daffodils => daffodils must be left of Bob
        # So Bob cannot be in the first house.
        if pos_name["Bob"] == 0:
            continue

        # Try all flower permutations
        for flowers_by_house in itertools.permutations(Flowers):
            pos_flower = {fl: i for i, fl in enumerate(flowers_by_house)}

            # 9) carnations immediately left of tulips
            if pos_flower["carnations"] + 1 != pos_flower["tulips"]:
                continue

            # 3) Peter is to the right of tulips
            if pos_name["Peter"] <= pos_flower["tulips"]:
                continue

            # 4) fish == daffodils combined with 7) fish directly left of Bob:
            # => daffodils must be directly left of Bob
            if pos_flower["daffodils"] + 1 != pos_name["Bob"]:
                continue

            # Try all animal permutations
            for animals_by_house in itertools.permutations(Animals):
                pos_animal = {an: i for i, an in enumerate(animals_by_house)}

                # 5) horse == Eric
                if pos_animal["horse"] != pos_name["Eric"]:
                    continue

                # 8) Alice directly left of horse
                if pos_name["Alice"] + 1 != pos_animal["horse"]:
                    continue

                # 2) lilies == bird
                if pos_flower["lilies"] != pos_animal["bird"]:
                    continue

                # 4) fish == daffodils
                if pos_animal["fish"] != pos_flower["daffodils"]:
                    continue

                # 7) fish directly left of Bob
                if pos_animal["fish"] + 1 != pos_name["Bob"]:
                    continue

                # 6) Two houses between dog owner and Bob (distance 3)
                if abs(pos_animal["dog"] - pos_name["Bob"]) != 3:
                    continue

                # 10) cat not in the first house
                if pos_animal["cat"] == 0:
                    continue

                # Passed all constraints; record solution
                solutions.append((names_by_house, flowers_by_house, animals_by_house))

    # Expect a unique solution
    if not solutions:
        raise RuntimeError("No solution found")
    # If multiple, take the first (puzzle should be unique)
    names_by_house, flowers_by_house, animals_by_house = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Flower", "Animal"],
            "rows": [
                [str(i + 1), names_by_house[i], flowers_by_house[i], animals_by_house[i]]
                for i in range(5)
            ],
        }
    }
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    solve()
